-- Delivery time: one of 1–2 days, 3–5 days, 1 week, 2 weeks.
UPDATE public.profile_services SET turnaround = CASE
  WHEN turnaround IN ('1–2 days', '3–5 days', '1 week', '2 weeks') THEN turnaround
  WHEN turnaround IN ('2 days', '48 hours') THEN '1–2 days'
  WHEN turnaround IN ('3 days', '4 days', '5 days', '3–5 days', 'Same week') THEN '3–5 days'
  WHEN turnaround IN ('5–7 days', '1 week''s notice', 'Book a week ahead', 'Starts within a week') THEN '1 week'
  WHEN turnaround IS NULL THEN '3–5 days'
  ELSE '2 weeks'
END;

-- Units read as words ("hr" → "hour").
UPDATE public.profile_services SET price_unit = 'hour' WHERE price_unit = 'hr';

-- Examples: the person's first two published portfolio works, featured first.
UPDATE public.profile_services s SET example_ids = coalesce((
  SELECT array_agg(x.id) FROM (
    SELECT id FROM public.portfolio_items
     WHERE user_id = s.profile_id AND published
     ORDER BY featured DESC, sort_order LIMIT 2) x), '{}')
 WHERE cardinality(s.example_ids) = 0;

COMMIT;
